<?php
require_once __DIR__.'/config.php'; require_once __DIR__.'/functions.php'; require_login();
$errors=[]; $title=''; $content=''; $category='General'; $tags=''; $status='draft';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $title=trim((string)($_POST['title']??'')); $content=trim((string)($_POST['content']??'')); $category=trim((string)($_POST['category']??'General')); $tags=trim((string)($_POST['tags']??'')); $status=(string)($_POST['status']??'draft');
 $errors=validate_post_input($title,$content,$category,$tags); if(!in_array($status,['draft','published'],true))$errors[]='Invalid post status.';
 $image=null; if(!$errors){[$image,$imageError]=upload_featured_image($_FILES['featured_image']??[]); if($imageError)$errors[]=$imageError;}
 if(!$errors){$st=$pdo->prepare('INSERT INTO posts(user_id,title,content,category,tags,status,featured_image) VALUES(:uid,:title,:content,:category,:tags,:status,:image)');$st->execute([':uid'=>(int)$_SESSION['user_id'],':title'=>$title,':content'=>$content,':category'=>$category,':tags'=>$tags,':status'=>$status,':image'=>$image]);redirect('dashboard.php?created=1');}
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create post | Blog Studio</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><a class="brand" href="index.php"><span class="brand-mark">B</span> Blog Studio</a><nav><a href="dashboard.php">Dashboard</a><a href="index.php">View blog</a></nav></header><main class="container narrow editor-page"><a href="dashboard.php">← Dashboard</a><p class="eyebrow">CONTENT STUDIO</p><h1>Create a story</h1><p class="muted">Write, organize and publish your next article.</p><?php foreach($errors as $error):?><p class="error"><?=e($error)?></p><?php endforeach;?>
<form class="editor-form" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label for="title">Post title</label><input id="title" name="title" maxlength="200" required value="<?=e($title)?>" placeholder="Give your story a clear title"><label for="content">Article content</label><textarea id="content" name="content" rows="14" maxlength="50000" required placeholder="Start writing your story..."><?=e($content)?></textarea><div class="form-grid"><div><label for="category">Category</label><select id="category" name="category"><?php foreach(['General','Technology','Lifestyle','Education','Business','Travel','Health','News'] as $cat):?><option <?= $category===$cat?'selected':''?>><?=e($cat)?></option><?php endforeach;?></select></div><div><label for="tags">Tags <span class="muted">(comma separated)</span></label><input id="tags" name="tags" maxlength="500" value="<?=e($tags)?>" placeholder="php, learning, web"></div></div><label for="featured_image">Featured image <span class="muted">(JPG, PNG, WebP · max 3 MB)</span></label><input id="featured_image" type="file" name="featured_image" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><label class="status-select">Save as <select name="status"><option value="draft" <?=$status==='draft'?'selected':''?>>Draft</option><option value="published" <?=$status==='published'?'selected':''?>>Published</option></select></label><button type="submit">Save post →</button></div></form></main></body></html>
